export function zipFiles(files){const enc=new TextEncoder(),local=[],central=[];let offset=0;const u16=(b,o,v)=>new DataView(b.buffer).setUint16(o,v,true),u32=(b,o,v)=>new DataView(b.buffer).setUint32(o,v>>>0,true);const crc=bytes=>{let n=0xffffffff;for(const x of bytes){n^=x;for(let i=0;i<8;i++)n=(n>>>1)^((n&1)?0xedb88320:0);}return (n^0xffffffff)>>>0;};for(const [name,value] of Object.entries(files)){const fn=enc.encode(name),data=enc.encode(typeof value==='string'?value:JSON.stringify(value)),checksum=crc(data),l=new Uint8Array(30+fn.length),c=new Uint8Array(46+fn.length);u32(l,0,0x04034b50);u16(l,4,20);u16(l,6,0x800);u32(l,14,checksum);u32(l,18,data.length);u32(l,22,data.length);u16(l,26,fn.length);l.set(fn,30);u32(c,0,0x02014b50);u16(c,4,20);u16(c,6,20);u16(c,8,0x800);u32(c,16,checksum);u32(c,20,data.length);u32(c,24,data.length);u16(c,28,fn.length);u32(c,42,offset);c.set(fn,46);local.push(l,data);central.push(c);offset+=l.length+data.length;}const size=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22);u32(end,0,0x06054b50);u16(end,8,central.length);u16(end,10,central.length);u32(end,12,size);u32(end,16,offset);return new Blob([...local,...central,end],{type:'application/zip'});}
